# R reference values for gaply_core::stats_dist's exact distribution of the
# Wilcoxon signed-rank statistic (Research OS, Phase 8Z-1, decision 637), the
# exact p of stats.analyze.related_ranks.
#
# Run by its full path, from anywhere:
#
#   /usr/local/bin/Rscript make_signed_rank_dist_fixtures.R
#
# R is the reference, run outside Gaply (ADR-008): nothing of R is copied into
# Gaply. Base R only (stats). make_dist_fixtures.R, make_xtab_dist_fixtures.R
# and make_ranks_dist_fixtures.R are separate scripts and are not run by this
# one, so their files are untouched. Writes, next to this script, one file with
# a '#' header naming this script, R's version and the call, then a CSV body
# with every number as %.17g:
#
#   signrank_p.csv  n,v,lower,upper   lower = psignrank(v, n)
#                                     upper = psignrank(v - 1, n, lower.tail = FALSE)
#
# so lower is P(V <= v) and upper is P(V >= v), V being the sum of the ranks of
# the positive differences among n non-zero differences with no ties.
#
# n from 1 to 49. Up to n = 20, every v from 0 to n (n + 1) / 2; above, v at 0,
# 1, 2, the centre (both integers next to the top / 2), the top three, and nine
# points spread evenly between.
#
# Synthetic grids only. No manuscript or data of anyone's is read.

args <- commandArgs(trailingOnly = FALSE)
script <- sub("^--file=", "", args[grep("^--file=", args)])
here <- dirname(normalizePath(script))

f17 <- function(x) sprintf("%.17g", as.numeric(x))

out <- list()
for (n in 1:49) {
  top <- n * (n + 1) / 2
  if (n <= 20) {
    v <- 0:top
  } else {
    v <- c(0, 1, 2, floor(top / 2), ceiling(top / 2), top - 2, top - 1, top,
           round(seq(0, top, length.out = 11))[2:10])
    v <- sort(unique(v[v >= 0 & v <= top]))
  }
  out[[length(out) + 1]] <- data.frame(
    n = f17(n), v = f17(v),
    lower = f17(psignrank(v, n)),
    upper = f17(psignrank(v - 1, n, lower.tail = FALSE)))
}
frame <- do.call(rbind, out)

path <- file.path(here, "signrank_p.csv")
writeLines(c(
  "# R's exact distribution of the Wilcoxon signed-rank statistic, for gaply_core::stats_dist (Research OS, Phase 8Z-1).",
  "# Generated by /usr/local/bin/Rscript make_signed_rank_dist_fixtures.R (do not edit by hand).",
  sprintf("# %s, %s; lower = psignrank(v, n), upper = psignrank(v - 1, n, lower.tail = FALSE).",
          R.version.string, R.version$arch)), path)
write.table(frame, path, sep = ",", quote = FALSE, row.names = FALSE, append = TRUE)
cat(sprintf("signrank_p.csv: %d rows\n", nrow(frame)))
